#include <stdlib.h>

int add(int a, int b) { return a + b; }
int inc(int x) { return x + 1; }

int parse(const char *s, int *out) {
    char *end;
    long v = strtol(s, &end, 10);
    if (*s == '\0' || *end != '\0') return -1;
    *out = (int)v;
    return 0;
}

